// Check and trigger combo milestone effects (blast + lift + charge)
// Uses >= with dedup set so skipping a milestone (e.g. 9→11) still triggers
function checkComboMilestone(fx,fy){
  const milestones=[10,20,30,50];
  for(let m of milestones){
    if(combo>=m&&!comboBlastTriggered.has(m)){
      comboBlastTriggered.add(m);
      comboBlast(fx,fy);
      liftAllBricks(m>=30?80:60);
      checkComboLift();
    }
  }
}

